package com.shailendra.product; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; @RestController @RequestMapping("/api/products") public class ProductController {record Product(long id,String name,BigDecimal price){} @GetMapping public List<Product> all(){return List.of(new Product(1,"Laptop",new BigDecimal("1299.00")),new Product(2,"Keyboard",new BigDecimal("99.00")));} @GetMapping("/{id}") public Product one(@PathVariable long id){return new Product(id,"Product-"+id,new BigDecimal("49.99"));}}